import{_ as l,W as i,X as a,a0 as e}from"./framework-715d567f.js";const p={},r=e('<h2 id="_1-日常知识点" tabindex="-1"><a class="header-anchor" href="#_1-日常知识点" aria-hidden="true">#</a> 1.日常知识点</h2><ul><li>量化时代，要每天关注量化的买入卖出，积极还是消极。每天关注大v们的情绪，观点，量化总是逆人性，大家都极度看好就砸了，极度悲观就又开始干活。</li><li>找准量化的节奏，规律</li><li>注意港股的大涨题材！会映射到A股的</li><li>市场缩量，没有指数行情的环境，可以考虑抱团或者创新药走个小周期</li><li>100%高度是一个门槛，要密切关注，个股是不是强势突破这个高度的</li></ul><h2 id="_2-星球布道" tabindex="-1"><a class="header-anchor" href="#_2-星球布道" aria-hidden="true">#</a> 2.星球布道</h2><h3 id="_0525" tabindex="-1"><a class="header-anchor" href="#_0525" aria-hidden="true">#</a> 0525</h3><p>那下一步就是观察这一批前排能不能破异动，破异动是检验是不是牛股的唯一标准</p><p>目前是中洲破了异动，那如果他能保持正反馈，那说明资金不畏高，因为刚100%嘛，那中洲连续负反馈的话那就是畏高了，然后就是海辰，永安，丽人，王子的表现了，这一批都能正反馈的话就是情绪很好的表现</p><p>总结：海辰没有负我，竞价加了下，因为有两个药业的一字助攻，经典的一字助攻手法了，后面就看能不能破异动了，然后是尾盘均线扫了点中洲，那时候就感觉是要上板，而且本来就很看见核聚变，觉得很像机器人，这个前面也写过的哈</p><p>心路历程，药是本来就比较看好的，因为基于我上面的思路，那就是抱团，然后药的机构持仓券商很小的，比电子，计算机的拥挤度小很多，多年没炒了，加上恒瑞这个权重趋势不错，在权重里面算是走势很好的</p><p>核聚变是很像前两年的机器人，中洲明显是量化模仿长盛的，也符合前面说话的做经典图形的思路，海辰大叶都是这样的，因为量化会去做</p><h3 id="_0529" tabindex="-1"><a class="header-anchor" href="#_0529" aria-hidden="true">#</a> 0529</h3><p>中毅达，大叶那一波算是大周期，一般大周期退下来要经历五浪，第一浪主升就是大叶这一波，然后是二浪下跌，三浪就是永安这一波，然后四浪永安下跌，这就是一波大周期退干净了，大周期下面孕育的是永安的小周期，小周期今天结束，所以下面应该是大周期，新周期 最核心的玉禾田，中邮，四方精创，雄帝科技，科捷基本都在了后面继续去弱留强就行了 6月感觉有大龙，因为抱团这个周期场外很多没参与的，高度打开了，大家都蠢蠢欲动</p><h2 id="_3-总结5月" tabindex="-1"><a class="header-anchor" href="#_3-总结5月" aria-hidden="true">#</a> 3.总结5月</h2><h3 id="大叶股份" tabindex="-1"><a class="header-anchor" href="#大叶股份" aria-hidden="true">#</a> 大叶股份</h3><p>0429</p><ul><li><p>按10日排名进入备选池（<strong>涨幅在35%~55%</strong>）；（联合化学股价太高，老周期化工）</p></li><li><p>首板解放3年平台，多年没炒；</p></li><li><p>有逻辑有业绩；</p></li><li><p>首板的长下影线，开盘高开下杀，洗掉埋伏盘</p></li></ul><p>0430</p><ul><li>对比其它20cm个股，表现最好；</li></ul><p>0506</p><ul><li><p>确认打市场地位。提示多点格局</p></li><li><p>先卖后买。因为<strong>大涨两天+10个点，止盈意愿强</strong>，所以卖；</p></li><li><p>但是<strong>上均线后跌不下去</strong>（均线上的时间多），<strong>地位高+承接好</strong>，就再买回</p></li></ul><p><img src="https://typora-imgbed-mrru.oss-cn-chengdu.aliyuncs.com/ruyb202507121057347.png" alt="image-20250602135605749" loading="lazy"></p><p>0507</p><ul><li>持股上涨</li><li>龙虎榜分析，量化大多锁仓</li></ul><p>0508</p><ul><li>手下震荡一天，次日能够破新高就行</li></ul><p>0509</p><ul><li>做T</li></ul><p>0513</p><ul><li>清仓</li></ul><p>0514</p><ul><li>买回，半仓，对标正丹二波</li><li>中午之前没板就算弱，次日可应用弱转强</li></ul><p>0515</p><ul><li>-1.5</li></ul><p>0516</p><ul><li>减完</li></ul><h3 id="海晨药业-低位小周期3天" tabindex="-1"><a class="header-anchor" href="#海晨药业-低位小周期3天" aria-hidden="true">#</a> 海晨药业--低位小周期3天</h3><p>0522</p><ul><li>3.5仓位</li></ul><p>0523</p><ul><li><p>开盘快速拉升 +5</p></li><li><p>8亿成交额没封住，减底仓</p></li></ul>',39),h=[r];function n(t,d){return i(),a("div",null,h)}const s=l(p,[["render",n],["__file","银河.html.vue"]]);export{s as default};
